mapper.insert:
insert into dh_folder(
    parent_folder_id, folder_name, normalized_name, owner_user_id, owner_user_name,
    sort_order, lock_version, del_flag, create_by, create_time, update_by, update_time, remark
) values (
    #{parentFolderId}, #{folderName}, #{normalizedName}, #{ownerUserId}, #{ownerUserName},
    #{sortOrder}, 0, '0', #{createBy}, sysdate(3), #{updateBy}, sysdate(3), #{remark}
)

mapper.delete:
delete i from dh_folder_item i left join dh_dataset d on d.dataset_id = i.dataset_id where i.folder_id = #{folderId} and i.owner_user_id = #{userId} and ( d.dataset_id is null or d.del_flag != '0' or d.status != 'ACTIVE'
or (d.owner_user_id != #{userId} and not exists ( select 1 from dh_dataset_acl a where a.dataset_id = d.dataset_id and mod(a.permission_mask, 2) = 1 and ( (a.subject_type = 'USER' and a.subject_id = #{userId}) or (a.subject_type = 'ROLE' and exists ( select 1 from sys_user_role ur join sys_role r on r.role_id = ur.role_id and r.status = '0' and r.del_flag = '0' where ur.user_id = #{userId} and ur.role_id = a.subject_id )) ) ))
)

mapper.select:
select * from dh_folder_item
where dataset_id = #{datasetId} and owner_user_id = #{userId}
for update

mapper.update:
update dh_folder_item
set folder_id = #{folderId}, lock_version = lock_version + 1,
    update_by = #{username}, update_time = sysdate(3)
where dataset_id = #{datasetId} and owner_user_id = #{userId}
  and lock_version = #{lockVersion}

mapper.delete:
delete from dh_folder_item
where dataset_id = #{datasetId} and owner_user_id = #{userId}
  and lock_version = #{lockVersion}
